                            ni, nj = i + di, j + dj
                            if 0 <= ni < n and 0 <= nj < n:
                                out[ni, nj] = True
        return out

    def erode(mask):
        out = np.ones_like(mask, dtype=bool)
        for i in range(n):
            for j in range(n):
                if not mask[i, j]:
                    out[i, j] = False
                    continue
                keep = True
                for di in (-1, 0, 1):
                    for dj in (-1, 0, 1):
