                    half_w = bridge_w / 2.0
                    b_low = (b_start - half_w) % 360.0
                    b_high = (b_start + half_w) % 360.0
                    if b_low <= b_high:
                        if b_low <= theta <= b_high:
                            in_bridge = True
                            break
                    else:
                        if theta >= b_low or theta <= b_high:
                            in_bridge = True
                            break

