        for i in range(n):
            for j in range(n):
                if mask[i, j]:
                    keep = True
                    for di in (-1, 0, 1):
                        for dj in (-1, 0, 1):
                            ni, nj = i + di, j + dj
                            if not (0 <= ni < n and 0 <= nj < n) or not mask[ni, nj]:
                                keep = False
                                break
                        if not keep:
                            break
                    if keep:
                        out[i, j] = True
        return out

    def dilate(mask):
        out = np.zeros_like(mask, dtype=bool)
        for i in range(n):
            for j in range(n):
                if mask[i, j]:
                    for di in (-1, 0, 1):
                        for dj in (-1, 0, 1):
                            ni, nj = i + di, j + dj
                            if 0 <= ni < n and 0 <= nj < n:
                                out[ni, nj] = True
        return out

    for _ in range(2):
        g = erode(g)
    for _ in range(2):
        g = dilate(g)

    # Flood-fill from chip to enforce 4-connectivity
    visit = np.zeros((n, n), dtype=bool)
    queue = []
    for i in range(i0, i1 + 1):
        for j in range(j0, j1 + 1):
            if 0 <= i < n and 0 <= j < n:
                visit[i, j] = True
                queue.append((i, j))
    while queue:
        i, j = queue.pop(0)
        for di, dj in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n and not visit[ni, nj] and g[ni, nj]:
                visit[ni, nj] = True
                queue.append((ni, nj))
    g &= visit

    # Enforce material budget: clip excess cells farthest from chip center
    if g.sum() > 1440:
        coords = np.argwhere(g)
        if len(coords) > 0:
            dists = (coords[:, 0] - cx) ** 2 + (coords[:, 1] - cy) ** 2
            idx_sorted = np.argsort(dists)  # ascending: closest first
            keep_idx = idx_sorted[:1440]
            g[:] = False
            for idx in keep_idx:
                i, j = coords[idx]
                g[i, j] = True

    return g
